import{at as e,it as t,n,vt as r}from"./chunks/framework.BIi0Nccc.js";var i=JSON.parse(`{"title":"Contributing","description":"","frontmatter":{"title":"Contributing"},"headers":[],"relativePath":"CONTRIBUTING/index.md","filePath":"CONTRIBUTING.md","lastUpdated":1793537972000}`),a={name:`CONTRIBUTING/index.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="contributing-to-bump-my-version" tabindex="-1">Contributing to Bump My Version <a class="header-anchor" href="#contributing-to-bump-my-version" aria-label="Permalink to “Contributing to Bump My Version”">​</a></h1><p>First off, thanks for taking the time to contribute! ❤️</p><p>All types of contributions are encouraged and valued. See the <a href="#table-of-contents">Table of Contents</a> for different ways to help and details about how this project handles them. Please make sure to read the relevant section before making your contribution. It will make it much easier for us maintainers and smooth out the experience for all involved. The community looks forward to your contributions. 🎉</p><blockquote><p>If you like the project but don&#39;t have time to contribute, that&#39;s fine. There are other easy ways to support the project and show your appreciation, which we would also be very happy about:</p><ul><li>Star the project</li><li>Tweet about it</li><li>Refer to this project in your project&#39;s readme</li><li>Mention the project at local meetups and tell your friends/colleagues</li></ul></blockquote><h2 id="table-of-contents" tabindex="-1">Table of Contents <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to “Table of Contents”">​</a></h2><ul><li><a href="#code-of-conduct">Code of Conduct</a></li><li><a href="#i-have-a-question">I Have a Question</a></li><li><a href="#reporting-bugs">Reporting Bugs</a></li><li><a href="#suggesting-enhancements">Suggesting Enhancements</a></li><li><a href="#your-first-code-contribution">Your First Code Contribution</a></li><li><a href="#improving-the-documentation">Improving The Documentation</a></li><li><a href="#styleguides">Styleguides</a></li><li><a href="#join-the-project-team">Join The Project Team</a></li></ul><h2 id="code-of-conduct" tabindex="-1">Code of Conduct <a class="header-anchor" href="#code-of-conduct" aria-label="Permalink to “Code of Conduct”">​</a></h2><p>This project and everyone participating in it are governed by the <a href="https://github.com/callowayproject/bump-my-versionblob/master/CODE_OF_CONDUCT.md" target="_blank" rel="noreferrer">Bump My Version Code of Conduct</a>. By participating, you are expected to uphold this code. Please report unacceptable behavior to <a href="mailto:coreyoordt@gmail.com" target="_blank" rel="noreferrer">mailto:coreyoordt@gmail.com</a>.</p><h2 id="i-have-a-question" tabindex="-1">I Have a Question <a class="header-anchor" href="#i-have-a-question" aria-label="Permalink to “I Have a Question”">​</a></h2><blockquote><p>If you want to ask a question, we assume that you have read the available <a href="https://callowayproject.github.io/bump-my-version/" target="_blank" rel="noreferrer">Documentation</a>.</p></blockquote><p>Before you ask a question, it is best to search for existing <a href="https://github.com/callowayproject/bump-my-version/issues" target="_blank" rel="noreferrer">Issues</a> that might help you. In case you have found a suitable issue and still need clarification, you can write your question in this issue. It is also advisable to search the internet for answers first.</p><p>If you then still feel the need to ask a question and need clarification, we recommend the following:</p><ul><li>Open an <a href="https://github.com/callowayproject/bump-my-version/issues/new" target="_blank" rel="noreferrer">Issue</a>.</li><li>Provide as much context as you can about what you&#39;re running into.</li><li>Provide project and platform versions (nodejs, npm, etc), depending on what seems relevant.</li></ul><p>We will then take care of the issue as soon as possible.</p><h2 id="reporting-bugs" tabindex="-1">Reporting Bugs <a class="header-anchor" href="#reporting-bugs" aria-label="Permalink to “Reporting Bugs”">​</a></h2><h3 id="before-submitting-a-bug-report" tabindex="-1">Before Submitting a Bug Report <a class="header-anchor" href="#before-submitting-a-bug-report" aria-label="Permalink to “Before Submitting a Bug Report”">​</a></h3><p>A good bug report shouldn&#39;t leave others needing to chase you up for more information. Therefore, we ask you to investigate carefully, collect information, and describe the issue in detail in your report. Please complete the following steps in advance to help us fix any potential bug as fast as possible.</p><ul><li>Make sure that you are using the latest version.</li><li>Determine if your bug is really a bug and not an error on your side e.g. using incompatible environment components/versions (Make sure that you have read the <a href="https://callowayproject.github.io/bump-my-version/" target="_blank" rel="noreferrer">documentation</a>. If you are looking for support, you might want to check <a href="#i-have-a-question">this section</a>).</li><li>To see if other users have experienced (and potentially already solved) the same issue you are having, check if there is not already a bug report existing for your bug or error in the <a href="https://github.com/callowayproject/bump-my-version/issues" target="_blank" rel="noreferrer">bug tracker</a>.</li><li>Also, make sure to search the internet (including Stack Overflow) to see if users outside of the GitHub community have discussed the issue.</li><li>Collect information about the bug: <ul><li>Stack trace (Traceback)</li><li>OS, Platform, and Version (Windows, Linux, macOS, x86, ARM)</li><li>The version of Python</li><li>Possibly your input and the output</li><li>Can you reliably reproduce the issue? And can you also reproduce it with older versions?</li></ul></li></ul><h3 id="how-do-i-submit-a-good-bug-report" tabindex="-1">How Do I Submit a Good Bug Report? <a class="header-anchor" href="#how-do-i-submit-a-good-bug-report" aria-label="Permalink to “How Do I Submit a Good Bug Report?”">​</a></h3><blockquote><p>You must never report security-related issues, vulnerabilities, or bugs that include sensitive information to the issue tracker or elsewhere in public. Instead, sensitive bugs must be sent by email to <a href="mailto:coreyoordt@gmail.com" target="_blank" rel="noreferrer">mailto:coreyoordt@gmail.com</a>.</p></blockquote><p>We use GitHub issues to track bugs and errors. If you run into an issue with the project:</p><ul><li>Open an <a href="https://github.com/callowayproject/bump-my-version/issues/new" target="_blank" rel="noreferrer">Issue</a>. (Since we can&#39;t be sure at this point whether it is a bug or not, we ask you not to talk about a bug yet and not to label the issue.)</li><li>Explain the behavior you would expect and the actual behavior.</li><li>Please provide as much context as possible and describe the <em>reproduction steps</em> that someone else can follow to recreate the issue on their own. This usually includes your code. For good bug reports, you should isolate the problem and create a reduced test case.</li><li>Provide the information you collected in the previous section.</li></ul><p>Once it&#39;s filed:</p><ul><li>The project team will label the issue accordingly.</li><li>A team member will try to reproduce the issue with your provided steps. If there are no reproduction steps or no obvious way to reproduce the issue, the team will ask you for those steps and will not address them until they are included.</li><li>If the team is able to reproduce the issue, the issue will be left to be <a href="#your-first-code-contribution">implemented by someone</a>.</li></ul><h2 id="suggesting-enhancements" tabindex="-1">Suggesting Enhancements <a class="header-anchor" href="#suggesting-enhancements" aria-label="Permalink to “Suggesting Enhancements”">​</a></h2><p>This section guides you through submitting an enhancement suggestion for Bump My Version, <strong>including completely new features and minor improvements to existing functionality</strong>. Following these guidelines will help maintainers and the community to understand your suggestion and find related suggestions.</p><h3 id="before-submitting-an-enhancement" tabindex="-1">Before Submitting an Enhancement <a class="header-anchor" href="#before-submitting-an-enhancement" aria-label="Permalink to “Before Submitting an Enhancement”">​</a></h3><ul><li>Make sure that you are using the latest version.</li><li>Read the <a href="https://callowayproject.github.io/bump-my-version/" target="_blank" rel="noreferrer">documentation</a> carefully and find out if the functionality is already covered, maybe by an individual configuration.</li><li>Perform a <a href="https://github.com/callowayproject/bump-my-version/issues" target="_blank" rel="noreferrer">search</a> to see if the enhancement has already been suggested. If it has, add a comment to the existing issue instead of opening a new one.</li><li>Find out whether your idea fits with the scope and aims of the project. It&#39;s up to you to make a strong case to convince the project&#39;s developers of the merits of this feature. Keep in mind that we want features that will be useful to the majority of our users and not just a small subset. If you&#39;re just targeting a minority of users, consider writing an add-on/plugin library.</li></ul><h3 id="how-do-i-submit-a-good-enhancement-suggestion" tabindex="-1">How Do I Submit a Good Enhancement Suggestion? <a class="header-anchor" href="#how-do-i-submit-a-good-enhancement-suggestion" aria-label="Permalink to “How Do I Submit a Good Enhancement Suggestion?”">​</a></h3><p>Enhancement suggestions are tracked as <a href="https://github.com/callowayproject/bump-my-version/issues" target="_blank" rel="noreferrer">GitHub issues</a>.</p><ul><li>Use a <strong>clear and descriptive title</strong> for the issue to identify the suggestion.</li><li><strong>Describe the problem or use case</strong> this enhancement solves <strong>or the new benefit</strong> it provides.</li><li><strong>Explain why this enhancement would be useful</strong> to most Bump My Version users. You may also want to point out the other projects that solved it better and which could serve as inspiration.</li><li>Provide a <strong>step-by-step description of the suggested enhancement</strong> in as many details as possible.</li><li>You may also tell how current alternatives do not work for you, if appropriate</li></ul><h2 id="your-first-code-contribution" tabindex="-1">Your First Code Contribution <a class="header-anchor" href="#your-first-code-contribution" aria-label="Permalink to “Your First Code Contribution”">​</a></h2><blockquote><h3 id="legal-notice" tabindex="-1">Legal Notice <a class="header-anchor" href="#legal-notice" aria-label="Permalink to “Legal Notice”">​</a></h3><p>When contributing to this project, you must agree that you have authored 100% of the content, that you have the necessary rights to the content and that the content you contribute may be provided under the project license.</p></blockquote><h3 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to “Setup”">​</a></h3><p>There are several ways to create an isolated Python development environment. This is the <a href="https://packaging.python.org/en/latest/guides/installing-using-pip-and-virtual-environments/#creating-a-virtual-environment" target="_blank" rel="noreferrer">default method</a>.</p><p>Run the following in a terminal:</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># Clone the repository</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/callowayproject/bump-my-version.git</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># Enter the repository</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bump-my-version</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># Create, then activate a virtual environment</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> venv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> env</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> env/bin/activate</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># Install the project in editable mode with its optional dependencies</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .[dev,test]</span></span></code></pre></div><p>If you are inclined to use the included <code>devenv.nix</code> environment, ensure you have both the <code>nix</code> package manager and <code>devenv</code> installed; reference the setup instructions for these tools <a href="http://devenv.sh/getting-started/" target="_blank" rel="noreferrer">in the getting started documentation</a>. Once <code>devenv</code> is installed, you can use the following command from the project&#39;s root directory:</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># Create and enter the devenv shell </span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">devenv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shell</span></span></code></pre></div><p>This will create an isolated shell with the necessary packages installed, as well as create the virtual environment for running the project using <code>uv</code>.</p><h3 id="run-tests" tabindex="-1">Run tests <a class="header-anchor" href="#run-tests" aria-label="Permalink to “Run tests”">​</a></h3><p>Once setup, you should be able to run tests:</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pytest</span></span></code></pre></div><h3 id="install-pre-commit-hooks" tabindex="-1">Install Pre-commit Hooks <a class="header-anchor" href="#install-pre-commit-hooks" aria-label="Permalink to “Install Pre-commit Hooks”">​</a></h3><p>Pre-commit hooks are scripts that run every time you make a commit. If any of the scripts fail, it stops the commit. You can see a listing of the checks in the <code>.pre-commit-config.yaml</code> file.</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pre-commit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><h2 id="improving-the-documentation" tabindex="-1">Improving The Documentation <a class="header-anchor" href="#improving-the-documentation" aria-label="Permalink to “Improving The Documentation”">​</a></h2><p>Please, please help us here.</p><h2 id="styleguides" tabindex="-1">Styleguides <a class="header-anchor" href="#styleguides" aria-label="Permalink to “Styleguides”">​</a></h2><h3 id="coding-style" tabindex="-1">Coding Style <a class="header-anchor" href="#coding-style" aria-label="Permalink to “Coding Style”">​</a></h3><p>All of the basic coding styles are configured into tools for fixing and checking them. <a href="https://pre-commit.com" target="_blank" rel="noreferrer">Pre-commit</a> is used to automate the process.</p><h3 id="commit-messages" tabindex="-1">Commit Messages <a class="header-anchor" href="#commit-messages" aria-label="Permalink to “Commit Messages”">​</a></h3><p>Commit messages are used to generate the change log.</p><h4 id="new-changes" tabindex="-1">New changes <a class="header-anchor" href="#new-changes" aria-label="Permalink to “New changes”">​</a></h4><p>Commit messages are categorized as &quot;new&quot; if the commit message starts with:</p><ul><li>new</li><li>add</li></ul><p>For example: <code>Added this cool new feature</code> or <code>New document type added</code>.</p><h4 id="updates" tabindex="-1">Updates <a class="header-anchor" href="#updates" aria-label="Permalink to “Updates”">​</a></h4><p>Commit messages are categorized as &quot;updates&quot; if the commit message starts with:</p><ul><li>update</li><li>change</li><li>rename</li><li>remove</li><li>delete</li><li>improve</li><li>refacto</li><li>chg</li><li>modif</li></ul><p>For example: <code>Modified the taxonomy schema</code> or <code>Improves performance by 419%</code></p><h4 id="fixes" tabindex="-1">Fixes <a class="header-anchor" href="#fixes" aria-label="Permalink to “Fixes”">​</a></h4><p>Commit messages are categorizes as &quot;fixes&quot; if the commit message starts with:</p><ul><li>fix</li></ul><p>For example: <code>Fixes bug #123</code></p><h4 id="other" tabindex="-1">Other <a class="header-anchor" href="#other" aria-label="Permalink to “Other”">​</a></h4><p>All other commit messages are categorized as &quot;other.&quot;</p><h4 id="ignoring-commit-messages" tabindex="-1">Ignoring commit messages <a class="header-anchor" href="#ignoring-commit-messages" aria-label="Permalink to “Ignoring commit messages”">​</a></h4><p>To have the change log generator ignore this commit, add to the summary line:</p><ul><li><code>@minor</code></li><li><code>!minor</code></li><li><code>@cosmetic</code></li><li><code>!cosmetic</code></li><li><code>@refactor</code></li><li><code>!refactor</code></li><li><code>@wip</code></li><li><code>!wip</code></li></ul><h2 id="join-the-project-team" tabindex="-1">Join The Project Team <a class="header-anchor" href="#join-the-project-team" aria-label="Permalink to “Join The Project Team”">​</a></h2><p>If you would like to be a maintainer, reach out to <a href="mailto:coreyoordt@gmail.com" target="_blank" rel="noreferrer">coreyoordt@gmail.com</a>.</p><h2 id="attribution" tabindex="-1">Attribution <a class="header-anchor" href="#attribution" aria-label="Permalink to “Attribution”">​</a></h2><p>This guide is based on the <strong>contributing-gen</strong>. <a href="https://github.com/bttger/contributing-gen" target="_blank" rel="noreferrer">Make your own</a>!</p>`,74)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};